import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0064: Computational Language Authoring","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0064-computational-language-authoring.md","filePath":"vendored/handl/project/adrs/0064-computational-language-authoring.md"}`),a={name:`handl/project/adrs/0064-computational-language-authoring.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0064-computational-language-authoring" tabindex="-1">ADR-0064: Computational Language Authoring <a class="header-anchor" href="#adr-0064-computational-language-authoring" aria-label="Permalink to “ADR-0064: Computational Language Authoring”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Proposed</p><p>Depends on <a href="./0063-scheme-core-completeness.html">ADR-0063 — Scheme-Core Completeness</a> (the core must be able to describe handl before handl is used to author languages). Refines <a href="./0044-language-as-data-and-runtime-split.html">ADR-0044 — Language as Data and Runtime Split</a> Phase 8 and <a href="./0041-languages-as-first-class-values.html">ADR-0041 — Languages as First-Class Values</a> §4 (language combinators as handl functions).</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>ADR-0044 made <code>Language</code> pure data: 7 YAML files, serde-serializable, embedded at compile time. This is declarative — but YAML is <em>literally</em> declarative. Transcribing the same literals into handl syntax gains nothing; the data is identical, the expressiveness is identical.</p><p>The actual win over YAML is <strong>computational authoring</strong>: handl functions that <em>generate</em>, <em>derive</em>, <em>parameterize</em>, and <em>abstract over</em> <code>Language</code> fragments. YAML cannot express &quot;a grammar row whose binding power is computed from the operator&#39;s arity&quot; or &quot;an eval scheme shared across all binary operators, parameterized by the operator name.&quot; handl can. This is the feature that makes authoring a language in handl worth doing, and it is what ADR-0041 §4 anticipated with <code>extend</code>/<code>merge</code>/<code>restrict</code> combinators — but those were specified as host functions, not as handl-level computation over fragment data.</p><h3 id="the-gap" tabindex="-1">The gap <a class="header-anchor" href="#the-gap" aria-label="Permalink to “The gap”">​</a></h3><p>Today, language authoring is:</p><ol><li>Hand-edit YAML files (declarative, static, no computation).</li><li>Embed at compile time via <code>include_str!</code> (ADR-0044 §6).</li></ol><p>What is missing:</p><ol start="3"><li>A handl program that <em>computes</em> a <code>Language</code> value — functions that take parameters and produce fragments, combinators that build fragment sets from smaller pieces, abstractions over repetitive structure.</li></ol><p>This is not &quot;declare the language in handl&quot; (that is just YAML with different syntax). It is &quot;write handl functions that generate the language.&quot; The distinction matters: the first is a format change with no new power; the second is a new authoring layer with real abstraction.</p><h3 id="why-this-depends-on-adr-0063" tabindex="-1">Why this depends on ADR-0063 <a class="header-anchor" href="#why-this-depends-on-adr-0063" aria-label="Permalink to “Why this depends on ADR-0063”">​</a></h3><p>If handl is used to author a <code>Language</code> value, and that <code>Language</code> value is then <code>eval</code>&#39;d, the eval must not require <code>Foreign</code> escapes for meta-operations (ADR-0063). Otherwise the authored language is not self-contained — it depends on host machinery that the authoring handl program cannot itself describe. Computational authoring on top of an incomplete core produces languages that look self-describing but secretly delegate to the host.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-fragment-constructors-as-handl-functions" tabindex="-1">1. Fragment constructors as handl functions <a class="header-anchor" href="#_1-fragment-constructors-as-handl-functions" aria-label="Permalink to “1. Fragment constructors as handl functions”">​</a></h3><p>Expose the fragment types (<code>TokenKindDef</code>, <code>GrammarRow</code>, <code>EvalSchemeDef</code>, <code>AstShapeDef</code>, <code>CapabilityDecl</code>, <code>OptionSchema</code>) as handl-callable constructors. A handl program builds fragments by calling functions, not by writing YAML:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># Instead of YAML:</span></span>
<span class="line"><span>#   - id: plus</span></span>
<span class="line"><span>#     position: infix</span></span>
<span class="line"><span>#     lbp: 20</span></span>
<span class="line"><span>#     rbp: 20</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Computational:</span></span>
<span class="line"><span>binary-op = fn(name, lbp, rbp) {</span></span>
<span class="line"><span>  grammar-row {</span></span>
<span class="line"><span>    id: name,</span></span>
<span class="line"><span>    position: &quot;infix&quot;,</span></span>
<span class="line"><span>    lbp: lbp,</span></span>
<span class="line"><span>    rbp: rbp,</span></span>
<span class="line"><span>    shape: [&quot;expr&quot;, &quot;expr&quot;],</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>plus  = binary-op(&quot;plus&quot;,  20, 20);</span></span>
<span class="line"><span>minus = binary-op(&quot;minus&quot;, 20, 20);</span></span>
<span class="line"><span>star  = binary-op(&quot;star&quot;,  40, 40);</span></span></code></pre></div><p>The <code>binary-op</code> function abstracts over a repetitive pattern. YAML cannot do this. This is the value.</p><h3 id="_2-fragment-set-combinators-as-handl-functions" tabindex="-1">2. Fragment-set combinators as handl functions <a class="header-anchor" href="#_2-fragment-set-combinators-as-handl-functions" aria-label="Permalink to “2. Fragment-set combinators as handl functions”">​</a></h3><p><code>Language::merge</code> (ADR-0044 §1) is exposed as a handl function. Fragment sets are built by composition:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>arith-ops = fragment-set([plus, minus, star, slash]);</span></span>
<span class="line"><span>compare-ops = fragment-set([eq, neq, lt, gt]);</span></span>
<span class="line"><span>all-ops = merge(arith-ops, compare-ops);</span></span></code></pre></div><p><code>extend</code>/<code>merge</code>/<code>restrict</code> (ADR-0041 §4) are handl functions over fragment sets, not host-side registry mutations. The result is a <code>Language</code> value — data, not a side effect.</p><h3 id="_3-parameterized-language-templates" tabindex="-1">3. Parameterized language templates <a class="header-anchor" href="#_3-parameterized-language-templates" aria-label="Permalink to “3. Parameterized language templates”">​</a></h3><p>A handl function can produce a <code>Language</code> parameterized by inputs:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>make-arith-lang = fn(ops, builtins) {</span></span>
<span class="line"><span>  language {</span></span>
<span class="line"><span>    tokens:  arith-tokens(ops),</span></span>
<span class="line"><span>    grammar: arith-grammar(ops),</span></span>
<span class="line"><span>    eval:    arith-eval(ops, builtins),</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>calc-lang = make-arith-lang([plus, minus, star], [sin, cos, sqrt]);</span></span></code></pre></div><p>This is the abstraction YAML cannot provide. A family of related languages (arith calculator, scientific calculator, matrix calculator) shares one parameterized definition.</p><h3 id="_4-the-authored-language-is-still-data" tabindex="-1">4. The authored <code>Language</code> is still data <a class="header-anchor" href="#_4-the-authored-language-is-still-data" aria-label="Permalink to “4. The authored Language is still data”">​</a></h3><p>The output of a handl authoring program is a <code>Language</code> value — the same serde-serializable data structure ADR-0044 defines. It can be serialized, cached (ADR-0065), chunked (ADR-0066), and certified (ADR-0067). The authoring path is a <em>build step</em> that produces data; the runtime consumes the data, not the authoring program.</p><p>This preserves ADR-0044&#39;s core property: <code>Language</code> is data, no Rust, no closures, no host-specific state. The authoring handl program runs at build time (or load time, with caching); the resulting <code>Language</code> is pure data at eval time.</p><h3 id="_5-yaml-remains-a-valid-authoring-path" tabindex="-1">5. YAML remains a valid authoring path <a class="header-anchor" href="#_5-yaml-remains-a-valid-authoring-path" aria-label="Permalink to “5. YAML remains a valid authoring path”">​</a></h3><p>YAML is not deprecated. It remains the simplest path for static, hand-written language definitions. Computational authoring is an <em>additional</em> path for languages that benefit from abstraction and parameterization. The two paths produce the same <code>Language</code> data structure and can be mixed: a YAML base with computationally generated extensions.</p><h3 id="_6-the-bootstrap-is-computational-authoring-of-handl-itself" tabindex="-1">6. The bootstrap is computational authoring of handl itself <a class="header-anchor" href="#_6-the-bootstrap-is-computational-authoring-of-handl-itself" aria-label="Permalink to “6. The bootstrap is computational authoring of handl itself”">​</a></h3><p>ADR-0044 Phase 8&#39;s <code>handl-defining-handl</code> is the canonical use case: a handl program that computes the <code>Language</code> value describing handl. With computational authoring, this is not a 5,000-line YAML file — it is a handl program that uses <code>binary-op</code>, <code>statement-form</code>, <code>desugar-rule</code> constructors to build the language with shared abstractions. The self-hosting bootstrap becomes a build step that runs the authoring program and serializes the result.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to “Positive”">​</a></h3><ul><li><strong>Abstraction over repetitive language structure.</strong> The <code>binary-op</code> pattern, the statement-form pattern, the desugar-rule pattern — all abstractable. Language definitions shrink and become maintainable.</li><li><strong>Parameterized language families.</strong> Related languages share a definition; differences are parameters, not copy-pasted YAML.</li><li><strong>The self-hosting bootstrap is a program, not a data file.</strong> handl defines itself via computation, which is both more compact and more honest than a YAML file that happens to describe handl.</li><li><strong>The output is still data.</strong> No runtime dependency on the authoring program. Caching, chunking, and certificates apply to the output.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to “Negative”">​</a></h3><ul><li><strong>Two authoring paths.</strong> YAML and handl programs coexist. The framework must accept both as fragment sources. This is the same migration-shape concern as ADR-0044 §6 (emitters vs data files), and the resolution is the same: both produce <code>Language</code> data; the path is invisible to the runtime.</li><li><strong>The authoring handl program must itself be evaluable.</strong> If handl cannot yet describe itself (ADR-0063 incomplete), the authoring program runs on the host-built handl, not the self-described one. This is fine for a build step but means the bootstrap is staged: host-built handl authors handl → self-described handl authors handl.</li><li><strong>Fragment constructors are a surface area.</strong> Every fragment type needs a handl-callable constructor with documented fields. This is a stable API that must be maintained as fragment types evolve.</li></ul><h3 id="neutral" tabindex="-1">Neutral <a class="header-anchor" href="#neutral" aria-label="Permalink to “Neutral”">​</a></h3><ul><li><strong>YAML is not going away.</strong> This ADR adds a path; it does not replace one. The choice is driven by whether the language definition benefits from computation.</li></ul><h2 id="implementation-phases" tabindex="-1">Implementation phases <a class="header-anchor" href="#implementation-phases" aria-label="Permalink to “Implementation phases”">​</a></h2><h3 id="phase-1-—-fragment-constructors" tabindex="-1">Phase 1 — Fragment constructors <a class="header-anchor" href="#phase-1-—-fragment-constructors" aria-label="Permalink to “Phase 1 — Fragment constructors”">​</a></h3><p>Expose <code>token-kind</code>, <code>grammar-row</code>, <code>eval-scheme</code>, <code>ast-shape</code>, <code>capability-decl</code>, <code>option-schema</code> as handl functions. Each takes named fields and returns a fragment value. This is a thin wrapper over the existing Rust constructors, exposed via the host-function mechanism (ADR-0040, ADR-0046).</p><h3 id="phase-2-—-fragment-set-and-language-combinators" tabindex="-1">Phase 2 — Fragment-set and Language combinators <a class="header-anchor" href="#phase-2-—-fragment-set-and-language-combinators" aria-label="Permalink to “Phase 2 — Fragment-set and Language combinators”">​</a></h3><p>Expose <code>fragment-set</code>, <code>merge</code>, <code>extend</code>, <code>restrict</code> as handl functions over fragment values. <code>merge</code> is <code>Language::merge</code> (ADR-0044 §5); <code>extend</code> is merge with override; <code>restrict</code> is fragment-set filtering.</p><h3 id="phase-3-—-authoring-examples" tabindex="-1">Phase 3 — Authoring examples <a class="header-anchor" href="#phase-3-—-authoring-examples" aria-label="Permalink to “Phase 3 — Authoring examples”">​</a></h3><p>Convert one or two sections of the canonical YAML to handl authoring programs (<code>binary-op</code> for arithmetic operators, <code>statement-form</code> for statement constructs). Verify the output <code>Language</code> matches the YAML-derived one via the conformance suite (ADR-0044 testing strategy).</p><h3 id="phase-4-—-handl-defining-handl-as-a-computational-authoring-program" tabindex="-1">Phase 4 — <code>handl-defining-handl</code> as a computational authoring program <a class="header-anchor" href="#phase-4-—-handl-defining-handl-as-a-computational-authoring-program" aria-label="Permalink to “Phase 4 — handl-defining-handl as a computational authoring program”">​</a></h3><p>Rewrite the self-hosting data file (from ADR-0063 Phase 3) as a handl authoring program using the constructors and combinators. The output must pass the same no-meta-<code>Foreign</code> and conformance assertions.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./0063-scheme-core-completeness.html">ADR-0063</a> — Scheme-Core Completeness (the gate; computational authoring on an incomplete core produces non-self-contained languages)</li><li><a href="./0044-language-as-data-and-runtime-split.html">ADR-0044</a> — Language as Data and Runtime Split (the data model; Phase 8 is the target)</li><li><a href="./0041-languages-as-first-class-values.html">ADR-0041</a> — Languages as First-Class Values (§4 anticipated language combinators as handl functions)</li><li><a href="./0052-arrow-calculus-kernel.html">ADR-0052</a> — Arrow Calculus Kernel (the core that the authoring program targets)</li><li><a href="./0046-capability-discipline-at-the-language-level.html">ADR-0046</a> — Capability Discipline (fragment constructors are host functions; they are capability-tracked)</li></ul>`,53)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};